  2	
  3	import java.time.Clock;
  4	import java.time.Duration;
  5	import java.time.Instant;
  6	import java.time.OffsetDateTime;
  7	import java.time.format.DateTimeParseException;
  8	import java.time.temporal.ChronoUnit;
  9	import java.util.List;
 10	import java.util.UUID;
 11	
 12	import org.springframework.stereotype.Service;
 13	import org.springframework.transaction.annotation.Transactional;
 14	import org.springframework.transaction.support.TransactionTemplate;
 15	
 16	import com.loja.orders.catalog.InventoryService;
 17	import com.loja.orders.checkout.CheckoutCalculator;
 18	import com.loja.orders.checkout.CheckoutRequest;
 19	import com.loja.orders.checkout.CheckoutSummary;
 20	import com.loja.orders.common.ApiException;
 21	import com.loja.orders.common.ErrorCode;
 22	import com.loja.orders.customer.CustomerRepository;
 23	
 24	@Service
 25	public class OrderService {
 26	
 27	    /** Pagamento que chega depois disso do registro do pedido não é aceito. */
 28	    private static final Duration PAYMENT_DEADLINE = Duration.ofHours(48);
 29	
 30	    private final CheckoutCalculator calculator;
 31	    private final OrderRepository orders;
 32	    private final CustomerRepository customers;
 33	    private final InventoryService inventory;
 34	    private final List<OrderLifecycleListener> listeners;
 35	    private final TransactionTemplate transaction;
 36	    private final Clock clock;
 37	
 38	    public OrderService(CheckoutCalculator calculator, OrderRepository orders, CustomerRepository customers,
 39	            InventoryService inventory, List<OrderLifecycleListener> listeners, TransactionTemplate transaction,
 40	            Clock clock) {
 41	        this.calculator = calculator;
 42	        this.orders = orders;
 43	        this.customers = customers;
 44	        this.inventory = inventory;
 45	        this.listeners = listeners;
 46	        this.transaction = transaction;
 47	        this.clock = clock;
 48	    }
 49	
 50	    public Order place(CheckoutRequest request) {
 51	        // O cálculo consulta a transportadora: fica fora da transação para não segurar o banco.
 52	        CheckoutSummary summary = calculator.calculate(request);
 53	        Order order = new Order(
 54	                UUID.randomUUID().toString(),
 55	                request.cpf(),
 56	                request.email(),
 57	                OrderStatus.AWAITING_PAYMENT,
 58	                Instant.now(clock).truncatedTo(ChronoUnit.SECONDS),
 59	                summary,
 60	                request.items(),
 61	                null);
 62	        transaction.executeWithoutResult(status -> {
 63	            customers.createIfAbsent(order.cpf());
 64	            orders.insert(order);
 65	        });
 66	        return order;
 67	    }
 68	
 69	    @Transactional(readOnly = true)
 70	    public Order get(String id) {
 71	        return orders.findById(id).orElseThrow(OrderService::notFound);
 72	    }
 73	
 74	    @Transactional(noRollbackFor = PaymentRejectedException.class)
 75	    public Order registerPayment(String id, String transactionId, String paidAtText) {
 76	        Order order = orders.lockById(id).orElseThrow(OrderService::notFound);
 77	        Instant paidAt = parseInstant(paidAtText);
 78	        if (transactionId == null || paidAt == null) {
 79	            throw ApiException.unprocessable(ErrorCode.INVALID_ORDER);
 80	        }
 81	        var previousNotice = orders.findPaymentNotice(id, transactionId);
 82	        if (previousNotice.isPresent()) {
 83	            return repeat(order, previousNotice.get());
 84	        }
 85	        requireTransition(order, OrderStatus.PAID);
 86	
 87	        if (Duration.between(order.createdAt(), paidAt).compareTo(PAYMENT_DEADLINE) > 0) {
 88	            return reject(order, transactionId, PaymentNoticeOutcome.ORDER_EXPIRED);
 89	        }
 90	        if (!inventory.take(order.items())) {
 91	            return reject(order, transactionId, PaymentNoticeOutcome.INSUFFICIENT_STOCK);
 92	        }
 93	        orders.markPaid(id, transactionId, paidAt);
 94	        orders.savePaymentNotice(id, transactionId, PaymentNoticeOutcome.ACCEPTED);
 95	        Order paid = reload(id);
 96	        listeners.forEach(listener -> listener.paymentApproved(paid));
 97	        return paid;
 98	    }
 99	
100	    @Transactional
101	    public Order ship(String id, String trackingCode) {
102	        Order order = orders.lockById(id).orElseThrow(OrderService::notFound);
103	        if (trackingCode == null) {
104	            throw ApiException.unprocessable(ErrorCode.INVALID_ORDER);
105	        }
106	        requireTransition(order, OrderStatus.SHIPPED);
107	        orders.markShipped(id, trackingCode);
108	        Order shipped = reload(id);
109	        listeners.forEach(listener -> listener.shipped(shipped));
110	        return shipped;
111	    }
112	
113	    @Transactional
114	    public Order deliver(String id) {
115	        Order order = orders.lockById(id).orElseThrow(OrderService::notFound);
116	        requireTransition(order, OrderStatus.DELIVERED);
117	        orders.updateStatus(id, OrderStatus.DELIVERED);
118	        return reload(id);
119	    }
120	
121	    @Transactional
122	    public Order cancel(String id) {
123	        Order order = orders.lockById(id).orElseThrow(OrderService::notFound);
124	        requireTransition(order, OrderStatus.CANCELLED);
125	        return cancelLocked(order);
126	    }
127	
128	    private Order repeat(Order order, PaymentNoticeOutcome outcome) {
129	        return switch (outcome) {
130	            case ACCEPTED -> order;
131	            case ORDER_EXPIRED -> throw new PaymentRejectedException(ErrorCode.ORDER_EXPIRED);
132	            case INSUFFICIENT_STOCK -> throw new PaymentRejectedException(ErrorCode.INSUFFICIENT_STOCK);
133	        };
134	    }
135	
136	    private Order reject(Order order, String transactionId, PaymentNoticeOutcome outcome) {
137	        orders.savePaymentNotice(order.id(), transactionId, outcome);
138	        cancelLocked(order);
139	        return repeat(order, outcome);
140	    }
141	
142	    private Order cancelLocked(Order order) {
143	        orders.updateStatus(order.id(), OrderStatus.CANCELLED);
144	        Order cancelled = reload(order.id());
145	        listeners.forEach(listener -> listener.cancelled(cancelled, order.status()));
146	        return cancelled;
147	    }
148	
149	    private Order reload(String id) {
150	        return orders.findById(id).orElseThrow(OrderService::notFound);
151	    }
152	
153	    private static void requireTransition(Order order, OrderStatus next) {
154	        if (!order.status().canMoveTo(next)) {
155	            throw ApiException.conflict(ErrorCode.OPERATION_NOT_ALLOWED);
156	        }
157	    }
158	
159	    private static Instant parseInstant(String text) {
160	        if (text == null) {
161	            return null;
162	        }
163	        try {
164	            return OffsetDateTime.parse(text).toInstant();
165	        } catch (DateTimeParseException e) {
166	            return null;
167	        }
168	    }
169	
170	    private static ApiException notFound() {
171	        return ApiException.notFound(ErrorCode.ORDER_NOT_FOUND);
172	    }
173	}
174	package com.loja.orders.catalog;
175	
176	import java.util.Comparator;
177	import java.util.List;
178	import java.util.Map;
179	
180	import org.springframework.stereotype.Service;
181	import org.springframework.transaction.annotation.Propagation;
182	import org.springframework.transaction.annotation.Transactional;
183	
184	import com.loja.orders.order.OrderItem;
185	
186	/**
187	 * Baixa e devolução de estoque. As linhas dos produtos ficam travadas até o fim da transação, então
188	 * dois pagamentos simultâneos da última peça nunca baixam o mesmo estoque duas vezes.
189	 */
190	@Service
191	public class InventoryService {
192	
193	    private final ProductRepository products;
194	
195	    public InventoryService(ProductRepository products) {
196	        this.products = products;
197	    }
198	
199	    /** Baixa o estoque de todos os itens, ou de nenhum se faltar algum. */
200	    @Transactional(propagation = Propagation.MANDATORY)
201	    public boolean take(List<OrderItem> items) {
202	        List<OrderItem> sorted = sortedBySku(items);
203	        Map<String, Integer> stock = products.lockStock(sorted.stream().map(OrderItem::sku).toList());
204	        boolean available = sorted.stream()
205	                .allMatch(item -> stock.getOrDefault(item.sku(), 0) >= item.quantity());
206	        if (!available) {
207	            return false;
208	        }
209	        sorted.forEach(item -> products.changeStock(item.sku(), -item.quantity()));
210	        return true;
211	    }
212	
213	    @Transactional(propagation = Propagation.MANDATORY)
214	    public void giveBack(List<OrderItem> items) {
215	        List<OrderItem> sorted = sortedBySku(items);
216	        products.lockStock(sorted.stream().map(OrderItem::sku).toList());
217	        sorted.forEach(item -> products.changeStock(item.sku(), item.quantity()));
218	    }
219	
220	    private static List<OrderItem> sortedBySku(List<OrderItem> items) {
221	        return items.stream().sorted(Comparator.comparing(OrderItem::sku)).toList();
222	    }
223	}
