241	@Repository
242	public class ProductRepository {
243	
244	    private final JdbcClient jdbc;
245	
246	    public ProductRepository(JdbcClient jdbc) {
247	        this.jdbc = jdbc;
248	    }
249	
250	    public Optional<Product> findBySku(String sku) {
251	        return jdbc.sql("SELECT * FROM product WHERE sku = :sku")
252	                .param("sku", sku)
253	                .query(ProductRepository::map)
254	                .optional();
255	    }
256	
257	    public Map<String, Product> findBySkus(Collection<String> skus) {
258	        if (skus.isEmpty()) {
259	            return Map.of();
260	        }
261	        return jdbc.sql("SELECT * FROM product WHERE sku IN (:skus)")
262	                .param("skus", skus)
263	                .query(ProductRepository::map)
264	                .list()
265	                .stream()
266	                .collect(Collectors.toMap(Product::sku, Function.identity()));
267	    }
268	
269	    /** Lê o estoque travando as linhas até o fim da transação, sempre na ordem do SKU. */
270	    public Map<String, Integer> lockStock(Collection<String> skus) {
271	        return jdbc.sql("SELECT sku, stock FROM product WHERE sku IN (:skus) ORDER BY sku FOR UPDATE")
272	                .param("skus", skus)
