236	/** Cotação de frete na TransLog ({@code GET {TRANSLOG_URL}/v2/quote}). */
237	@Component
238	public class TranslogCarrier implements Carrier {
239	
240	    private static final String ZIP_NOT_SERVED = "ZIP_NOT_SERVED";
241	
242	    private final String baseUrl;
243	    private final Duration timeout;
244	    private final JsonMapper mapper;
245	    private final HttpClient http;
246	
247	    public TranslogCarrier(@Value("${translog.url:}") String baseUrl,
248	            @Value("${translog.timeout:2s}") Duration timeout, JsonMapper mapper) {
249	        this.baseUrl = baseUrl.strip().replaceAll("/+$", "");
250	        this.timeout = timeout;
251	        this.mapper = mapper;
252	        this.http = HttpClient.newBuilder().version(HttpClient.Version.HTTP_1_1).connectTimeout(timeout).build();
253	    }
254	
255	    @Override
256	    public CarrierQuote quote(String zipCode, int weightGrams, CarrierService service) {
257	        if (baseUrl.isEmpty()) {
258	            throw new CarrierUnavailableException("TRANSLOG_URL não configurada");
259	        }
260	        URI uri;
261	        try {
262	            uri = URI.create(baseUrl + "/v2/quote"
263	                    + "?zip=" + URLEncoder.encode(zipCode, StandardCharsets.UTF_8)
264	                    + "&weight_g=" + weightGrams
265	                    + "&service=" + serviceCode(service));
266	        } catch (IllegalArgumentException e) {
267	            throw new CarrierUnavailableException("TRANSLOG_URL inválida", e);
268	        }
269	        HttpResponse<String> response = get(uri);
270	        if (response.statusCode() != 200) {
271	            throw new CarrierUnavailableException("TransLog respondeu " + response.statusCode());
272	        }
273	        return parse(response.body());
274	    }
275	
276	    private HttpResponse<String> get(URI uri) {
277	        CompletableFuture<HttpResponse<String>> call;
278	        try {
279	            HttpRequest request = HttpRequest.newBuilder(uri).timeout(timeout).GET().build();
280	            call = http.sendAsync(request, HttpResponse.BodyHandlers.ofString());
281	        } catch (IllegalArgumentException e) {
282	            throw new CarrierUnavailableException("TRANSLOG_URL inválida", e);
283	        }
284	        try {
285	            // O prazo vale para a resposta inteira, não só para a conexão.
286	            return call.get(timeout.toMillis(), TimeUnit.MILLISECONDS);
287	        } catch (TimeoutException e) {
288	            call.cancel(true);
289	            throw new CarrierUnavailableException("TransLog não respondeu a tempo", e);
290	        } catch (ExecutionException e) {
291	            throw new CarrierUnavailableException("Falha ao chamar a TransLog", e.getCause());
292	        } catch (InterruptedException e) {
293	            Thread.currentThread().interrupt();
294	            call.cancel(true);
295	            throw new CarrierUnavailableException("Chamada à TransLog interrompida", e);
296	        }
297	    }
