299	    private CarrierQuote parse(String body) {
300	        JsonNode json;
301	        try {
302	            json = mapper.readTree(body);
303	        } catch (JacksonException e) {
304	            throw new CarrierUnavailableException("Resposta inválida da TransLog", e);
305	        }
306	        if (json == null || !json.isObject()) {
307	            throw new CarrierUnavailableException("Resposta inválida da TransLog");
308	        }
309	        if (json.has("error")) {
310	            JsonNode error = json.get("error");
311	            if (error.isString() && ZIP_NOT_SERVED.equals(error.stringValue())) {
312	                throw new ZipNotServedException();
313	            }
314	            throw new CarrierUnavailableException("TransLog respondeu erro " + error);
315	        }
316	        JsonNode cents = json.path("price_cents");
317	        JsonNode hours = json.path("eta_hours");
318	        if (!isNonNegativeInt(cents) || !isNonNegativeInt(hours)) {
319	            throw new CarrierUnavailableException("Resposta incompleta da TransLog");
320	        }
321	        return new CarrierQuote(BigDecimal.valueOf(cents.asLong(), 2), hours.asInt());
322	    }
323	
324	    private static boolean isNonNegativeInt(JsonNode node) {
325	        return node.isNumber() && node.canConvertToExactIntegral() && node.canConvertToInt() && node.asInt() >= 0;
326	    }
327	
328	    private static String serviceCode(CarrierService service) {
329	        return switch (service) {
330	            case STANDARD -> "STD";
331	            case EXPRESS -> "EXP";
332	        };
333	    }
