141	/** Lê os dados da compra e faz a primeira conferência: carrinho e cliente ({@code INVALID_ORDER}). */
142	@Component
143	public class CheckoutRequestParser {
144	
145	    private final JsonBodies bodies;
146	
147	    public CheckoutRequestParser(JsonBodies bodies) {
148	        this.bodies = bodies;
149	    }
150	
151	    public CheckoutRequest parse(String body) {
152	        JsonNode root = bodies.read(body);
153	        if (!root.isObject()) {
154	            throw invalidOrder();
155	        }
156	        List<OrderItem> items = items(root.path("items"));
157	        JsonNode customer = root.path("customer");
158	        String cpf = JsonBodies.text(customer, "cpf");
159	        String email = JsonBodies.text(customer, "email");
160	        if (cpf == null || email == null) {
161	            throw invalidOrder();
162	        }
163	        JsonNode coupon = root.path("coupon");
164	        boolean couponInformed = !coupon.isMissingNode() && !coupon.isNull();
165	        return new CheckoutRequest(
166	                cpf,
167	                email,
168	                items,
169	                JsonBodies.text(root, "zipCode"),
170	                JsonBodies.text(root, "region"),
171	                JsonBodies.text(root, "shippingMethod"),
172	                couponInformed,
173	                coupon.isString() ? coupon.stringValue() : null,
174	                JsonBodies.text(root, "paymentMethod"),
175	                installments(root.path("installments")),
176	                JsonBodies.text(root, "clubTier"));
177	    }
178	
179	    private static List<OrderItem> items(JsonNode node) {
180	        if (!node.isArray() || node.isEmpty()) {
181	            throw invalidOrder();
182	        }
183	        List<OrderItem> items = new ArrayList<>();
184	        Set<String> skus = new HashSet<>();
185	        for (JsonNode item : node) {
186	            String sku = JsonBodies.text(item, "sku");
187	            Integer quantity = integer(item.path("quantity"));
188	            if (sku == null || !skus.add(sku) || quantity == null || quantity <= 0) {
189	                throw invalidOrder();
190	            }
191	            items.add(new OrderItem(sku, quantity));
192	        }
193	        return List.copyOf(items);
194	    }
195	
196	    private static Integer installments(JsonNode node) {
197	        if (node.isMissingNode() || node.isNull()) {
198	            return 1;
199	        }
200	        return integer(node);
201	    }
202	
203	    private static Integer integer(JsonNode node) {
204	        if (!node.isNumber() || !node.canConvertToExactIntegral() || !node.canConvertToInt()) {
205	            return null;
206	        }
207	        return node.asInt();
208	    }
209	
210	    private static ApiException invalidOrder() {
211	        return ApiException.unprocessable(ErrorCode.INVALID_ORDER);
212	    }
213	}
