package com.loja.orders.catalog;



/** Quando um pedido pago é cancelado, o estoque volta. */
@Component
public class StockReturnListener implements OrderLifecycleListener {

    private final InventoryService inventory;

    public StockReturnListener(InventoryService inventory) {
        this.inventory = inventory;
    }

    @Override
    public void cancelled(Order order, OrderStatus previousStatus) {
        if (previousStatus.paymentSettled()) {
            inventory.giveBack(order.items());
        }
    }
}
package com.loja.orders.customer;



/** O crédito do clube entra no saldo quando o pagamento é confirmado e sai se o pedido pago é cancelado. */
@Component
public class ClubCreditListener implements OrderLifecycleListener {

    private final CustomerRepository customers;

    public ClubCreditListener(CustomerRepository customers) {
        this.customers = customers;
    }

    @Override
    public void paymentApproved(Order order) {
        customers.addCredit(order.cpf(), order.summary().nextPurchaseCredit());
    }

    @Override
    public void cancelled(Order order, OrderStatus previousStatus) {
        if (previousStatus.paymentSettled()) {
            customers.addCredit(order.cpf(), order.summary().nextPurchaseCredit().negate());
        }
    }
}
package com.loja.orders.notification;



/** Avisa o cliente: por enquanto, o aviso fica na lista que o atendimento consulta. */
@Component
public class CustomerNotificationListener implements OrderLifecycleListener {

    private final NotificationRepository notifications;

    public CustomerNotificationListener(NotificationRepository notifications) {
        this.notifications = notifications;
    }

    @Override
    public void paymentApproved(Order order) {
        notifications.add(order.cpf(), order.id(), NotificationType.PAYMENT_APPROVED);
    }

