import com.sun.net.httpserver.*;
import java.net.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

public class Stub {
    static volatile String body = "{\"price_cents\": 3310, \"eta_hours\": 41}";
    static volatile int status = 200;
    static volatile long delay = 0;
    static final List<String> log = Collections.synchronizedList(new ArrayList<>());

    static Map<String,String> q(URI u) {
        Map<String,String> m = new HashMap<>();
        String raw = u.getRawQuery();
        if (raw == null) return m;
        for (String p : raw.split("&")) {
            String[] kv = p.split("=", 2);
            m.put(URLDecoder.decode(kv[0], StandardCharsets.UTF_8), kv.length > 1 ? URLDecoder.decode(kv[1], StandardCharsets.UTF_8) : "");
        }
        return m;
    }
    static void send(HttpExchange ex, int st, String b) throws IOException {
        byte[] bytes = b.getBytes(StandardCharsets.UTF_8);
        ex.getResponseHeaders().set("Content-Type", "application/json");
        ex.sendResponseHeaders(st, bytes.length);
        ex.getResponseBody().write(bytes);
        ex.close();
    }
    public static void main(String[] a) throws Exception {
        int port = Integer.parseInt(a.length > 0 ? a[0] : "9099");
        HttpServer s = HttpServer.create(new InetSocketAddress(port), 0);
        s.setExecutor(java.util.concurrent.Executors.newCachedThreadPool());
        s.createContext("/__set", ex -> {
            Map<String,String> m = q(ex.getRequestURI());
            if (m.containsKey("body")) body = m.get("body");
            if (m.containsKey("status")) status = Integer.parseInt(m.get("status"));
            if (m.containsKey("delay")) delay = Long.parseLong(m.get("delay"));
            send(ex, 200, "ok");
        });
        s.createContext("/__log", ex -> {
            String out;
            synchronized (log) { out = String.join("\n", log); log.clear(); }
            send(ex, 200, out);
        });
        s.createContext("/v2/quote", ex -> {
            log.add(ex.getRequestMethod() + " " + ex.getRequestURI());
            try { if (delay > 0) Thread.sleep(delay); } catch (InterruptedException e) {}
            try { send(ex, status, body); } catch (IOException e) {}
        });
        s.start();
        System.out.println("stub on " + port);
    }
}
