import java.net.URI;
import java.net.http.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.regex.*;

public class Race {
    static HttpClient http = HttpClient.newHttpClient();
    static String NOW = java.time.Instant.now().truncatedTo(java.time.temporal.ChronoUnit.SECONDS).toString();
    static HttpResponse<String> post(int port, String path, String body) throws Exception {
        return http.send(HttpRequest.newBuilder(URI.create("http://localhost:" + port + path))
            .header("Content-Type", "application/json").POST(HttpRequest.BodyPublishers.ofString(body)).build(),
            HttpResponse.BodyHandlers.ofString());
    }
    static String get(int port, String path) throws Exception {
        return http.send(HttpRequest.newBuilder(URI.create("http://localhost:" + port + path)).build(), HttpResponse.BodyHandlers.ofString()).body();
    }
    static String field(String json, String f) {
        Matcher m = Pattern.compile("\"" + f + "\":\"?([^\",}]*)").matcher(json); return m.find() ? m.group(1) : null;
    }
    static String order(int port, String cpf, String items) throws Exception {
        var r = post(port, "/orders", "{\"customer\":{\"cpf\":\"" + cpf + "\",\"email\":\"r@x.com\"},\"items\":" + items
            + ",\"zipCode\":\"01310100\",\"region\":\"SOUTH\",\"shippingMethod\":\"STORE_PICKUP\",\"paymentMethod\":\"CREDIT_CARD\",\"clubTier\":\"SILVER\"}");
        if (r.statusCode() != 201) throw new RuntimeException("place " + r.statusCode() + " " + r.body());
        return field(r.body(), "id");
    }
    static int stock(String sku) throws Exception { return Integer.parseInt(field(get(8081, "/products/" + sku), "stock")); }
    static HttpResponse<String>[] together(int portA, String pathA, String bodyA, int portB, String pathB, String bodyB) throws Exception {
        CyclicBarrier barrier = new CyclicBarrier(2);
        ExecutorService ex = Executors.newFixedThreadPool(2);
        Future<HttpResponse<String>> fa = ex.submit(() -> { barrier.await(); return post(portA, pathA, bodyA); });
        Future<HttpResponse<String>> fb = ex.submit(() -> { barrier.await(); return post(portB, pathB, bodyB); });
        @SuppressWarnings("unchecked") HttpResponse<String>[] out = new HttpResponse[]{fa.get(), fb.get()};
        ex.shutdown(); return out;
    }
    static String pay(String tx) { return "{\"transactionId\":\"" + tx + "\",\"paidAt\":\"" + NOW + "\"}"; }

    public static void main(String[] a) throws Exception {
        int rounds = Integer.parseInt(a[0]);
        // warm-up
        get(8081, "/products/MOC-001"); get(8082, "/products/MOC-001");
        int ok = 0, bad = 0, aWins = 0, bWins = 0;
        for (int r = 0; r < rounds; r++) {
            String A = order(8081, "4000000000" + (r % 10), "[{\"sku\":\"MOC-001\",\"quantity\":1}]");
            String B = order(8082, "4100000000" + (r % 10), "[{\"sku\":\"MOC-001\",\"quantity\":1}]");
            var res = together(8081, "/orders/" + A + "/payment", pay("RA" + r), 8082, "/orders/" + B + "/payment", pay("RB" + r));
            int s = stock("MOC-001");
            int ca = res[0].statusCode(), cb = res[1].statusCode();
            boolean good = ((ca == 200 && cb == 409 && res[1].body().contains("INSUFFICIENT_STOCK")) || (cb == 200 && ca == 409 && res[0].body().contains("INSUFFICIENT_STOCK"))) && s == 0;
            if (good) ok++; else { bad++; System.out.println("PROBLEMA round " + r + ": " + ca + " " + res[0].body() + " | " + cb + " " + res[1].body() + " stock=" + s); }
            if (ca == 200) aWins++; if (cb == 200) bWins++;
            String w = ca == 200 ? A : B;
            if (ca == 200 && cb == 200) { post(8081, "/orders/" + A + "/cancellation", ""); post(8081, "/orders/" + B + "/cancellation", ""); }
            else post(8082, "/orders/" + w + "/cancellation", "");
        }
        System.out.println("ultima peca: ok=" + ok + " problemas=" + bad + " (A venceu " + aWins + ", B venceu " + bWins + ") MOC final=" + stock("MOC-001"));

        // pedidos com itens cruzados (risco de deadlock), estoque exato para um só
        int fon = stock("FON-001"), jaq = stock("JAQ-001");
        int okx = 0, badx = 0;
        for (int r = 0; r < rounds; r++) {
            String A = order(8081, "4200000000" + (r % 10), "[{\"sku\":\"JAQ-001\",\"quantity\":" + jaq + "},{\"sku\":\"FON-001\",\"quantity\":" + fon + "}]");
            String B = order(8082, "4300000000" + (r % 10), "[{\"sku\":\"FON-001\",\"quantity\":" + fon + "},{\"sku\":\"JAQ-001\",\"quantity\":" + jaq + "}]");
            long t0 = System.nanoTime();
            var res = together(8081, "/orders/" + A + "/payment", pay("XA" + r), 8082, "/orders/" + B + "/payment", pay("XB" + r));
            long ms = (System.nanoTime() - t0) / 1_000_000;
            int ca = res[0].statusCode(), cb = res[1].statusCode();
            int sf = stock("FON-001"), sj = stock("JAQ-001");
            boolean good = ((ca == 200 && cb == 409) || (ca == 409 && cb == 200)) && sf == 0 && sj == 0;
            if (good) okx++; else { badx++; System.out.println("PROBLEMA cruzado " + r + ": " + ca + " " + res[0].body() + " | " + cb + " " + res[1].body() + " fon=" + sf + " jaq=" + sj + " " + ms + "ms"); }
            post(8081, "/orders/" + (ca == 200 ? A : B) + "/cancellation", "");
        }
        System.out.println("cruzados: ok=" + okx + " problemas=" + badx + " FON=" + stock("FON-001") + " JAQ=" + stock("JAQ-001"));

        // mesmo aviso nas duas maquinas ao mesmo tempo
        int okd = 0, badd = 0;
        for (int r = 0; r < rounds; r++) {
            String cpf = "4400000000" + (r % 10);
            String before = field(get(8081, "/customers/" + cpf), "creditBalance");
            int m0 = stock("MEI-001");
            String A = order(8081, cpf, "[{\"sku\":\"MEI-001\",\"quantity\":2}]");
            if (before == null) before = "0.00";
            var res = together(8081, "/orders/" + A + "/payment", pay("DUP" + r), 8082, "/orders/" + A + "/payment", pay("DUP" + r));
            int m1 = stock("MEI-001");
            String after = field(get(8081, "/customers/" + cpf), "creditBalance");
            String notes = get(8081, "/customers/" + cpf + "/notifications");
            long approvals = Pattern.compile(A + "\",\"status").matcher(notes).results().count();
            boolean good = res[0].statusCode() == 200 && res[1].statusCode() == 200 && res[0].body().equals(res[1].body()) && m0 - m1 == 2
                && new java.math.BigDecimal(after).subtract(new java.math.BigDecimal(before)).compareTo(new java.math.BigDecimal("0.80")) == 0 && approvals == 1;
            if (good) okd++; else { badd++; System.out.println("PROBLEMA dup " + r + ": " + res[0].statusCode() + " " + res[1].statusCode() + " " + res[1].body() + " estoque " + m0 + "->" + m1 + " credito " + before + "->" + after + " avisos=" + approvals); }
        }
        System.out.println("aviso duplicado simultaneo: ok=" + okd + " problemas=" + badd);
    }
}
